import numpy as np
from scipy import ndimage

def comps(g, bgc):
    g = np.array([[int(x) for x in row] for row in g])
    lab, n = ndimage.label(g != bgc)
    out = []
    for i in range(1, n+1):
        rc = np.argwhere(lab == i)
        cells = {(int(r), int(c)) for r, c in rc}
        col = {int(g[r, c]) for r, c in cells}.pop()
        out.append((col, cells))
    return out

def mindist(a, b):
    return min(np.hypot(r1-r2, c1-c2) for r1, c1 in a for r2, c2 in b)

def analyze(name, inp, outp, bgc):
    changed = {(int(r), int(c)) for r, c in np.argwhere(np.array([[int(x) for x in row] for row in inp]) != np.array([[int(x) for x in row] for row in outp]))}
    cs = comps(inp, bgc)
    src = [(col, c) for col, c in cs if c & changed][0]
    ranks = []
    for col, c in cs:
        rest = set().union(*[x for cc, x in cs if x is not c])
        ranks.append((round(mindist(c, rest), 2), col, min(r for r, _ in c), min(cc for _, cc in c), len(c)))
    ranks.sort(reverse=True)
    print(name, "src: col %d size %d iso %s" % (src[0], len(src[1]), mindist(src[1], set().union(*[x for cc, x in cs if x is not src[1]]))))
    for rk in ranks: print("   iso=%.2f col=%d topr=%d topc=%d size=%d" % rk)
    return src

